const sleep=ms=>new Promise(r=>setTimeout(r,ms));
const safe=s=>s.replace(/\.html$/,'').replace(/[^a-z0-9_-]+/gi,'-')||'index';
const hash=s=>crypto.createHash('sha256').update(s||'').digest('hex');

async function sweep(page){await page.evaluate(async()=>{await new Promise(resolve=>{let y=0;const tick=()=>{const max=Math.max(document.body.scrollHeight,document.documentElement.scrollHeight);y+=700;scrollTo(0,Math.min(y,max));if(y>=max)setTimeout(()=>{scrollTo(0,0);resolve()},250);else setTimeout(tick,50)};tick()})})}

async function focusAudit(page){await page.evaluate(()=>scrollTo(0,0));const rows=[];for(let i=0;i<10;i++){await page.keyboard.press('Tab');rows.push(await page.evaluate(()=>{const e=document.activeElement;if(!e)return null;const s=getComputedStyle(e),r=e.getBoundingClientRect();return{tag:e.tagName.toLowerCase(),id:e.id||'',class:typeof e.className==='string'?e.className:'',text:(e.innerText||e.getAttribute('aria-label')||'').trim().slice(0,90),outlineStyle:s.outlineStyle,outlineWidth:s.outlineWidth,outlineColor:s.outlineColor,boxShadow:s.boxShadow,rect:{left:Math.round(r.left),top:Math.round(r.top),width:Math.round(r.width),height:Math.round(r.height)}}}))}return rows.filter(Boolean)}

async function filmAudit(page){return await page.evaluate(()=>{const video=document.getElementById('holding-film'),hero=document.querySelector('.hero-film-hero'),shell=document.querySelector('.hero-film-shell'),sound=document.querySelector('[data-film-sound]'),controls=[...document.querySelectorAll('.hero-film-controls button,.hero-film-controls input')];if(!video||!hero||!shell)return null;const vr=video.getBoundingClientRect(),hr=hero.getBoundingClientRect(),sr=shell.getBoundingClientRect(),cs=getComputedStyle(video);const iw=video.videoWidth||1280,ih=video.videoHeight||720;let rendered={width:vr.width,height:vr.height},visibleX=1,visibleY=1,cropX=0,cropY=0;if(cs.objectFit==='cover'&&iw&&ih){const scale=Math.max(vr.width/iw,vr.height/ih),cw=iw*scale,ch=ih*scale;visibleX=Math.min(1,vr.width/cw);visibleY=Math.min(1,vr.height/ch);cropX=1-visibleX;cropY=1-visibleY;rendered={width:cw,height:ch}}else if(cs.objectFit==='contain'&&iw&&ih){const scale=Math.min(vr.width/iw,vr.height/ih);rendered={width:iw*scale,height:ih*scale}}const rect=e=>{const r=e.getBoundingClientRect();return{left:r.left,top:r.top,right:r.right,bottom:r.bottom,width:r.width,height:r.height}};return{intrinsic:{width:iw,height:ih,ratio:iw/ih},hero:{...rect(hero),ratio:hr.width/hr.height,overflow:getComputedStyle(hero).overflow},shell:{...rect(shell),overflow:getComputedStyle(shell).overflow},videoBox:rect(video),objectFit:cs.objectFit,objectPosition:cs.objectPosition,coverRendered:rendered,visibleSourceFraction:{x:visibleX,y:visibleY},croppedSourceFraction:{x:cropX,y:cropY},soundCTA:sound?{hidden:sound.hidden,text:sound.textContent.trim(),rect:rect(sound)}:null,controls:controls.map(e=>{const s=getComputedStyle(e);return{label:e.getAttribute('aria-label')||e.textContent.trim(),hidden:e.hidden,display:s.display,visibility:s.visibility,rect:rect(e)}}),captions:{tracks:video.textTracks?video.textTracks.length:0,trackModes:video.textTracks?[...video.textTracks].map(t=>({kind:t.kind,label:t.label,mode:t.mode})):[]}}})}

async function navAudit(page,route,vp){const state=await page.evaluate(()=>{const t=document.querySelector('.menu-toggle'),n=document.querySelector('#primary-nav');if(!t||!n)return null;const ts=getComputedStyle(t),ns=getComputedStyle(n);return{toggleDisplay:ts.display,toggleVisible:ts.display!=='none'&&ts.visibility!=='hidden',expanded:t.getAttribute('aria-expanded'),navDisplay:ns.display,navVisibility:ns.visibility,bodyNavOpen:document.body.classList.contains('nav-open')}});if(state?.toggleVisible){await page.click('.menu-toggle');await sleep(150);const opened=await page.evaluate(()=>({expanded:document.querySelector('.menu-toggle')?.getAttribute('aria-expanded'),bodyNavOpen:document.body.classList.contains('nav-open'),activeTag:document.activeElement?.tagName?.toLowerCase()||'',activeText:(document.activeElement?.textContent||document.activeElement?.getAttribute?.('aria-label')||'').trim().slice(0,80)}));if(vp.width<=768)await page.screenshot({path:`gate-a/nav-open/${safe(route)}-${vp.name}.jpg`,type:'jpeg',quality:72});await page.keyboard.press('Escape');await sleep(100);const closed=await page.evaluate(()=>({expanded:document.querySelector('.menu-toggle')?.getAttribute('aria-expanded'),bodyNavOpen:document.body.classList.contains('nav-open'),activeTag:document.activeElement?.tagName?.toLowerCase()||'',activeText:(document.activeElement?.textContent||document.activeElement?.getAttribute?.('aria-label')||'').trim().slice(0,80)}));return{initial:state,opened,closed}}return{initial:state}}

(async()=>{const browser=await puppeteer.launch({headless:true,executablePath:process.env.CHROME,args:['--no-sandbox','--disable-dev-shm-usage','--autoplay-policy=user-gesture-required']});const report={productSha:PRODUCT,routes:{},linkRecords:[]};for(const route of routes){report.routes[route]={};for(const vp of viewports){const page=await browser.newPage(),consoleErrors=[],pageErrors=[],requestFailures=[];page.on('console',m=>{if(m.type()==='error')consoleErrors.push(m.text())});page.on('pageerror',e=>pageErrors.push(String(e)));page.on('requestfailed',r=>requestFailures.push({url:r.url(),error:r.failure()?.errorText||''}));await page.setViewport({width:vp.width,height:vp.height,deviceScaleFactor:1});const response=await page.goto(`http://127.0.0.1:8000/${route}`,{waitUntil:'domcontentloaded',timeout:30000});await page.evaluate(()=>document.fonts?.ready||Promise.resolve());await sleep(250);const routeName=safe(route);await page.screenshot({path:`gate-a/screenshots/${routeName}-${vp.name}-viewport.jpg`,type:'jpeg',quality:76});await sweep(page);await sleep(150);const metrics=await page.evaluate(()=>{const vw=document.documentElement.clientWidth,overflow=[],clipped=[],images=[];const rect=e=>{if(!e)return null;const r=e.getBoundingClientRect();return{left:Math.round(r.left),top:Math.round(r.top),right:Math.round(r.right),bottom:Math.round(r.bottom),width:Math.round(r.width),height:Math.round(r.height)}};for(const el of document.querySelectorAll('body *')){const s=getComputedStyle(el),r=el.getBoundingClientRect();if(!r.width||!r.height||s.display==='none'||s.visibility==='hidden')continue;if(s.position!=='fixed'&&s.position!=='sticky'&&(r.right>vw+2||r.left<-2)){overflow.push({tag:el.tagName.toLowerCase(),id:el.id||'',class:typeof el.className==='string'?el.className:'',left:Math.round(r.left),right:Math.round(r.right),width:Math.round(r.width)});if(overflow.length>=40)break}}for(const el of document.querySelectorAll('h1,h2,h3,h4,h5,h6,p,a,button,label,li,td,th,span')){const s=getComputedStyle(el),r=el.getBoundingClientRect(),txt=(el.innerText||el.textContent||'').trim();if(!txt||!r.width||!r.height||s.display==='none'||s.visibility==='hidden')continue;const xClip=el.scrollWidth>el.clientWidth+2&&(s.overflowX==='hidden'||s.overflowX==='clip'||s.whiteSpace==='nowrap'),yClip=el.scrollHeight>el.clientHeight+2&&(s.overflowY==='hidden'||s.overflowY==='clip');if(xClip||yClip)clipped.push({tag:el.tagName.toLowerCase(),text:txt.slice(0,100),xClip,yClip,clientWidth:el.clientWidth,scrollWidth:el.scrollWidth,clientHeight:el.clientHeight,scrollHeight:el.scrollHeight,overflowX:s.overflowX,overflowY:s.overflowY,whiteSpace:s.whiteSpace});if(clipped.length>=40)break}for(const img of document.images){const r=img.getBoundingClientRect(),s=getComputedStyle(img);images.push({src:img.getAttribute('src')||'',complete:img.complete,naturalWidth:img.naturalWidth,naturalHeight:img.naturalHeight,renderedWidth:Math.round(r.width),renderedHeight:Math.round(r.height),objectFit:s.objectFit,objectPosition:s.objectPosition})}const h=document.querySelector('[data-header]'),f=document.querySelector('footer.site-footer'),m=document.querySelector('main'),nav=document.querySelector('#primary-nav');const ctas=[...document.querySelectorAll('main a,main button')].filter(e=>{const r=e.getBoundingClientRect(),s=getComputedStyle(e);return r.width>0&&r.height>0&&s.display!=='none'&&s.visibility!=='hidden'}).slice(0,30).map(e=>({text:(e.innerText||e.getAttribute('aria-label')||'').trim().slice(0,100),href:e.getAttribute('href')||null,rect:rect(e)}));const mainChildren=m?[...m.children].map(e=>({tag:e.tagName.toLowerCase(),class:typeof e.className==='string'?e.className:'',rect:rect(e)})):[],gaps=[];for(let i=1;i<mainChildren.length;i++){const a=mainChildren[i-1].rect,b=mainChildren[i].rect;if(a&&b){const g=b.top-a.bottom;if(g>180)gaps.push({after:mainChildren[i-1].class,before:mainChildren[i].class,gap:Math.round(g)})}}return{viewport:{width:innerWidth,height:innerHeight},scrollWidth:document.documentElement.scrollWidth,scrollHeight:document.documentElement.scrollHeight,horizontalOverflow:document.documentElement.scrollWidth>vw+2,overflow,clipped,images,header:rect(h),footer:rect(f),main:rect(m),nav:rect(nav),h1s:[...document.querySelectorAll('main h1')].map(e=>(e.innerText||e.textContent||'').trim()),ctas,mainChildren,gaps,bodyBg:getComputedStyle(document.body).backgroundColor,bodyColor:getComputedStyle(document.body).color,headerHtml:h?h.outerHTML:'',footerHtml:f?f.outerHTML:''}});const navState=await navAudit(page,route,vp),focus=await focusAudit(page),film=route==='index.html'&&vp.width<=768?await filmAudit(page):null;if(vp.name==='1440x900'){fs.writeFileSync(`gate-a/visible-text/${routeName}.txt`,await page.evaluate(()=>document.body.innerText));const links=await page.evaluate(()=>[...document.querySelectorAll('a[href]')].map(a=>({href:a.getAttribute('href'),label:(a.innerText||a.getAttribute('aria-label')||'').trim().replace(/\s+/g,' ').slice(0,180),target:a.getAttribute('target')||'',rel:a.getAttribute('rel')||''})));report.linkRecords.push(...links.map(l=>({source:route,...l})))}await page.screenshot({path:`gate-a/screenshots/${routeName}-${vp.name}-full.jpg`,type:'jpeg',quality:66,fullPage:true});report.routes[route][vp.name]={status:response?.status()||null,...metrics,headerHash:hash(metrics.headerHtml),footerHash:hash(metrics.footerHtml),consoleErrors,pageErrors,requestFailures,navState,focus,film};delete report.routes[route][vp.name].headerHtml;delete report.routes[route][vp.name].footerHtml;await page.close()}}
const uniq=new Map();for(const rec of report.linkRecords){const key=[rec.source,rec.href,rec.label].join('|');if(!uniq.has(key))uniq.set(key,rec)}report.linkRecords=[...uniq.values()];const internal=[],esc=s=>s.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');for(const rec of report.linkRecords){if(!rec.href||/^(mailto:|tel:|javascript:)/i.test(rec.href))continue;let u;try{u=new URL(rec.href,`http://127.0.0.1:8000/${rec.source}`)}catch{continue}if(u.hostname!=='127.0.0.1')continue;const target=u.pathname.replace(/^\//,'')||'index.html';let status=null,fragmentOk=true,error=null;try{const res=await fetch(`http://127.0.0.1:8000/${target}`);status=res.status;if(u.hash){const text=await res.text(),id=decodeURIComponent(u.hash.slice(1));fragmentOk=new RegExp(`(?:id|name)=["']${esc(id)}["']`,'i').test(text)}}catch(e){error=String(e)}internal.push({...rec,target,fragment:u.hash||'',status,fragmentOk,error,automatedClass:(!status||status>=400||!fragmentOk)?'BROKEN':'PASS'})}report.internalLinks=internal;fs.writeFileSync('gate-a/reports/browser-audit.json',JSON.stringify(report,null,2));fs.writeFileSync('gate-a/reports/link-audit.json',JSON.stringify(internal,null,2));fs.writeFileSync('gate-a/reports/homepage-film.json',JSON.stringify({productSha:PRODUCT,index:report.routes['index.html']},null,2));await browser.close()})().catch(e=>{console.error(e);process.exit(1)});
